// PetDeleteOne builds the delete of one `pets` row. Start one with
// `Graph.pets().delete_one(node)` or `delete_one_id(id)`.
pub struct PetDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q PetQuery) delete_one(node PetNode) PetDeleteOne {
	return q.delete_one_id(node.pet.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q PetQuery) delete_one_id(id int) PetDeleteOne {
	return PetDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'pets'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b PetDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'pets'
		}
	}
}

// PetDelete builds the delete of the `pets` rows that match its conditions.
// Start one with `Graph.pets().delete()`.
pub struct PetDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q PetQuery) delete() PetDelete {
	return PetDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'pets'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b PetDelete) where(conds ...load.Cond) PetDelete {
	return PetDelete{
		...b
		data: b.data.with_conds(conds)
	}
}

